    "onboarding.script.greeting.systemsOnline": "系统已上线。",
    "onboarding.script.greeting.capability":
      "我可以自然地和你对话，跨工具执行真实工作，并记住你喜欢的协作方式。",
    "onboarding.script.askName": "开始之前，你想怎么称呼我？",
    "onboarding.script.confirmName.named":
      "{name}。好名字。我会在每次对话里沿用它。",
    "onboarding.script.confirmName.default":
      "那我就叫 NeoWorker。随时可以开始。",
    "onboarding.script.askAssistantTraits":
      "你希望我是怎样的助手？选择符合你偏好的选项。",
    "onboarding.script.confirmAssistantTraits":
      "好。我已经知道这个角色的大致形状了。接下来了解一下我在和谁一起工作。",
    "onboarding.script.askUserProfile": "我应该怎么称呼你？",
    "onboarding.script.confirmUserProfile":
      "收到。我会这样称呼你，让一开始就更有个人感。",
    "onboarding.script.askTimeDrains":
      "你的时间最常被哪些事情拖走？选择那些真正消耗你一天的东西。",
    "onboarding.script.confirmTimeDrains":
      "很好。这些正是我应该重点留意的瓶颈。",
    "onboarding.script.askPriorities":
      "结合你刚才说的内容，你最想先让我帮什么？选择你的优先事项。",
    "onboarding.script.confirmPriorities":
      "很好。这个具体程度足够我从一开始就围绕它优化。",
    "onboarding.script.askTools":
      "哪些应用或工具是你工作流的核心？把我应该当作主场的工具也写上。",
    "onboarding.script.confirmTools":
      "好。我会把这些工具栈当作你的工作表面，而不是每次都从零开始。",
    "onboarding.script.askResponseStyle": "你喜欢怎样的回复方式？",
    "onboarding.script.confirmResponseStyle":
      "明白。除非任务明显需要不同方式，我会保持这种回复形态。",
    "onboarding.script.askAdditionalGuidance":
      "设置前最后一件事：有没有什么你希望我始终记住的偏好？",
    "onboarding.script.confirmAdditionalGuidance":
      "好。我会把它作为和你协作方式的一部分带着。",
    "onboarding.script.askVoice": "在有帮助的时候，你想让我用语音回复吗？",
    "onboarding.script.confirmVoiceOn": "很好。我会在语音能增加清晰度时开口。",
    "onboarding.script.confirmVoiceOff": "没问题。我们先保持文本优先。",
    "onboarding.script.askWorkStyle":
      "我想匹配你的节奏。你更喜欢清晰计划，还是灵活执行？",
    "onboarding.script.reflectStylePlanner":
      "很好。我会把工作结构化，并保持进度可见。",
    "onboarding.script.reflectStyleFlexible":
      "很好。我会快速推进，并随着上下文变化调整。",
    "onboarding.script.stylePlanner.plan": "• 我会把工作拆成清晰的分步计划",
    "onboarding.script.stylePlanner.updates":
      "• 你会收到稳定更新和明确的下一步",
    "onboarding.script.stylePlanner.memory":
      "• 我会记住重复模式，让以后的任务启动更快",
    "onboarding.script.styleFlexible.fast": "• 我会快速开始，并实时调整",
    "onboarding.script.styleFlexible.iterate":
      "• 我们会快速迭代，而不是一开始过度规划",
    "onboarding.script.styleFlexible.context": "• 我会把对话里的上下文延续下去",
    "onboarding.script.askMemoryTrust":
      "继续前有一个信任设置：决定我是否应该记住跨对话有帮助的上下文。",
    "onboarding.script.confirmMemoryTrustOn":
      "很好。我会保留有用偏好和上下文，你随时可以编辑或删除记忆。",
    "onboarding.script.confirmMemoryTrustOff":
      "明白。我会完全关闭记忆，暂时不存储任何记忆。之后你可以在 设置 > 记忆 中启用。",
