    "welcome.card.write.prompt":
      "我有一个写作任务想让你帮忙。我会描述需求，我们一起完成。",
    "welcome.card.research.prompt":
      "我需要研究一个主题。我来告诉你具体想了解什么。",
    "welcome.card.analyze.prompt":
      "我有一些数据想分析。我会分享文件，并说明我想找到什么。",
    "welcome.card.files.prompt":
      "我需要处理一些文件。我会告诉你文件夹位置，并说明需要做什么。",
    "welcome.card.build.prompt": "我需要构建或编写一些东西。我来描述这个项目。",
    "welcome.card.chat.prompt": "我们先聊聊。我有件事想一起梳理一下。",
    "welcome.card.meeting.prompt": "帮我准备一次会议。我需要议程和讨论要点。",
    "welcome.card.document.prompt":
      "我需要创建一份文档。我会说明需要的格式和内容。",
    "welcome.card.email.prompt": "帮我起草一封邮件。我会提供背景和收件人信息。",
    "welcome.card.summarize.prompt": "我有内容需要总结。我会把内容发给你。",
    "welcome.card.code.prompt":
      "我有一些代码需要帮助。我会分享代码并说明问题。",
    "welcome.card.translate.prompt":
      "我需要翻译一些内容。我会提供原文和目标语言。",
    "welcome.card.morning-brief.prompt":
      "请为我生成每日简报。如果日历、收件箱、任务和工作区上下文已连接，请结合这些信息。包括今天的日程、紧急消息、未完成承诺，以及下一步最重要的 3 个行动。",
    "welcome.card.inbox-triage.prompt":
      "请整理我的收件箱。如果 Gmail 或其他邮箱已连接，请找出需要回复的消息、紧急决策、跟进事项、等待项和可安全归档的候选项。采取任何操作前先询问我。",
    "welcome.card.slide-deck.prompt":
      "请根据我提供的材料制作一套幻灯片。先询问受众和目标，然后创建清晰大纲、每页文案、演讲备注，并生成打磨好的演示文稿产物。",
    "welcome.card.spreadsheet-model.prompt":
      "请根据我描述的工作流创建一份电子表格。先询问输入项和需要支持的决策，然后创建包含公式、摘要和清晰标签页的结构化工作簿。",
    "welcome.card.transcribe-audio.prompt":
      "请帮我转录一个音频或视频文件。我分享文件后，请输出干净的转录稿、关键要点、决策和行动项。",
    "welcome.card.build-automation.prompt":
      "帮我自动化一个重复工作流。请询问它的触发条件、需要哪些信息、应该执行哪些动作，以及哪些敏感步骤需要审批。",
    "welcome.card.decision-memo.prompt":
      "帮我比较几个选项。我会描述决策、约束和候选方案。请生成一份决策备忘录，包含权衡、风险、未知项和建议。",
    "welcome.card.competitors.prompt":
      "请调研我将描述的市场中排名前 3-5 的竞品。对每个竞品找出定位、关键功能、价格、优势和弱点，然后指出我可以利用的空白机会。",
    "welcome.card.research-vault.prompt":
      "我想在当前 NeoWorker 工作区建立一个长期研究资料库。请先询问研究主题、范围和资料来源，然后创建清晰的目录结构、来源索引、研究笔记、待整理收件箱和后续维护计划。",
    "welcome.card.validate-idea.prompt":
      "帮我验证一个商业想法。我会描述概念，请评估市场规模、竞品、独特切入点，并给出是否推进的建议。",
    "welcome.card.weekly-plan.prompt":
      "帮我制定一周计划。请询问我的目标、截止日期和优先级，然后生成按天安排、交付物清晰的计划。",
    "welcome.card.discover-memory.prompt": "你记得哪些关于我和我的偏好的信息？",
    "welcome.card.discover-browse.prompt":
      "请搜索我接下来会描述的主题的最新消息。",
    "welcome.card.discover-files.prompt": "请告诉我当前工作区里有哪些文件。",
    "welcome.card.discover-agents.prompt":
      "我有一个需要多步骤完成的复杂任务。我会描述目标，请你帮我规划步骤。",
    "welcome.card.discover-documents.prompt":
      "请告诉我你能在这个工作区创建哪些文档、PDF、幻灯片和电子表格。",
    "welcome.card.discover-images.prompt":
      "我想分析一张图片或截图。请告诉我你能检查哪些内容，以及我上传时最好提供哪些细节。",
    "welcome.card.discover-tests.prompt":
      "请检查这个项目是否有质量问题。先查看可用脚本，推荐合适的构建、Lint 或测试命令，并运行最安全的定向检查。",
    "welcome.card.discover-vault.prompt":
      "请检查当前 NeoWorker 工作区中的研究资料，找出值得继续探索的主题关联、资料缺口和下一步行动，并把可长期保留的发现整理回工作区。",
