let currentLanguage: SupportedLanguage = DEFAULT_LANGUAGE;
const listeners = new Set<() => void>();

export function normalizeLanguage(lang?: string | null): SupportedLanguage {
  const normalized = String(lang || "")
    .trim()
    .toLowerCase();
  if (
    normalized === "zh" ||
    normalized === "zh-cn" ||
    normalized === "zh-hans"
  ) {
    return "zh-CN";
  }
  if (normalized === "en" || normalized.startsWith("en-")) {
    return "en";
  }
  return DEFAULT_LANGUAGE;
}

function setRuntimeLanguage(lang: SupportedLanguage): SupportedLanguage {
  if (typeof document !== "undefined") {
    document.documentElement.lang = lang;
  }
  if (currentLanguage === lang) return currentLanguage;
  currentLanguage = lang;
  try {
    if (typeof window !== "undefined") {
      window.localStorage.setItem(LANGUAGE_STORAGE_KEY, lang);
    }
  } catch {
    // Non-critical: persistence also happens through appearance settings.
  }
  listeners.forEach((listener) => listener());
  return currentLanguage;
}

export function getCurrentLanguage(): SupportedLanguage {
  return currentLanguage;
}

export function subscribeLanguage(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function useLanguage(): SupportedLanguage {
  return useSyncExternalStore(
    subscribeLanguage,
    getCurrentLanguage,
    getCurrentLanguage,
  );
}

export function translate(
  key: string,
  fallback?: string,
  values?: Record<string, string | number | null | undefined>,
): string {
  const template =
    translations[currentLanguage]?.[key] ??
    translations.en[key] ??
    fallback ??
    key;
  if (!values) return template;
  return template.replace(/\{(\w+)\}/g, (match, token) => {
    const value = values[token];
    return value === null || value === undefined ? match : String(value);
  });
}

export function applyPersistedLanguage(lang?: string): SupportedLanguage {
  if (lang) return setRuntimeLanguage(normalizeLanguage(lang));
  try {
    const saved =
      typeof window !== "undefined"
        ? window.localStorage.getItem(LANGUAGE_STORAGE_KEY)
        : null;
    return setRuntimeLanguage(normalizeLanguage(saved));
  } catch {
    return setRuntimeLanguage(DEFAULT_LANGUAGE);
  }
}

export async function changeLanguage(lang: SupportedLanguage): Promise<void> {
  const previousLanguage = currentLanguage;
  const nextLanguage = setRuntimeLanguage(normalizeLanguage(lang));
  try {
    if (
      typeof window !== "undefined" &&
      window.electronAPI?.saveAppearanceSettings
    ) {
      await window.electronAPI.saveAppearanceSettings({
        language: nextLanguage,
      });
    }
  } catch {
    // Non-critical; the UI can continue with the current language.
  }

  // Some catalog/configuration data is intentionally defined at module scope.
  // Re-initialize the renderer after an explicit language change so those
  // translated constants are rebuilt in the selected language as well.
  if (
    previousLanguage !== nextLanguage &&
    typeof window !== "undefined" &&
    typeof window.location?.reload === "function"
  ) {
    window.location.reload();
  }
}
